from pysat import SATSolver
from pysat.card import CardEnc

N = 6
total = N * N

def knight_moves(cell):
    r = cell // N
    c = cell % N
    moves = []
    for dr, dc in [(1,2),(1,-2),(-1,2),(-1,-2),(2,1),(2,-1),(-2,1),(-2,-1)]:
        nr, nc = r + dr, c + dc
        if 0 <= nr < N and 0 <= nc < N:
            moves.append(nr * N + nc)
    return moves

adj = {i: knight_moves(i) for i in range(total)}

# Create variables: var(i, c) = step i, cell c
# We'll use a mapping from (i, c) to integer variable ID
var = {}
counter = 1
for i in range(total):
    for c in range(total):
        var[(i, c)] = counter
        counter += 1

print("Number of variables:", counter-1)

# Create solver
solver = SATSolver()

# 1. Each step has exactly one cell
for i in range(total):
    clause = [var[(i, c)] for c in range(total)]
    # At least one
    solver.add_clause(clause)
    # At most one: pairwise
    for c1 in range(total):
        for c2 in range(c1+1, total):
            solver.add_clause([-var[(i, c1)], -var[(i, c2)]])

# 2. Each cell appears exactly once (permutation)
for c in range(total):
    clause = [var[(i, c)] for i in range(total)]
    solver.add_clause(clause)
    for i1 in range(total):
        for i2 in range(i1+1, total):
            solver.add_clause([-var[(i1, c)], -var[(i2, c)]])

# 3. Knight move constraints: for each step i (0..34), if x[i]=a and x[i+1]=b, then b in adj[a]
# Equivalent: forbid (x[i]=a AND x[i+1]=b) for b not in adj[a]
for i in range(total - 1):
    for a in range(total):
        for b in range(total):
            if b not in adj[a]:
                # forbid a at step i and b at step i+1
                solver.add_clause([-var[(i, a)], -var[(i+1, b)]])

# 4. Fixed assignments
fixed = {0: 0, 3: 17, 6: 24, 17: 30, 19: 6, 29: 25, 32: 21, 34: 23}
for step, cell in fixed.items():
    solver.add_clause([var[(step, cell)]])

print("Clauses added, solving...")
status = solver.solve()
print("Status:", status)

if status:
    model = solver.get_model()
    # Extract solution
    solution = [None] * total
    for i in range(total):
        for c in range(total):
            if var[(i, c)] in model:
                solution[i] = c
                break
    print("Solution:", solution)
    # Verify
    ok = True
    for i in range(total - 1):
        if solution[i+1] not in adj[solution[i]]:
            print(f"Error: step {i}: {solution[i]} -> {solution[i+1]} not a knight move")
            ok = False
    if ok:
        print("All moves valid!")
    # Check permutation
    if sorted(solution) == list(range(total)):
        print("Valid permutation!")
    else:
        print("Not a permutation!")
else:
    print("UNSAT")

